def icon_svg(name,color):
 return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="{color}" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">{ICONS[name]}</svg>'
def icon(name,color,size=22,ratio=2):
 """Icon als QIcon; für Retina mit doppelter Auflösung gerendert."""
 renderer=QSvgRenderer(QByteArray(icon_svg(name,color).encode()));pixmap=QPixmap(size*ratio,size*ratio);pixmap.fill(Qt.transparent)
 painter=QPainter(pixmap);renderer.render(painter);painter.end();pixmap.setDevicePixelRatio(ratio);result=QIcon();result.addPixmap(pixmap);return result
